prompt --application/shared_components/user_interface/lovs/time_lov
begin
wwv_flow_api.create_list_of_values(
 p_id=>wwv_flow_api.id(1747655392131265618)
,p_lov_name=>'TIME_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ss || '':'' || dd || '' '' || am ss_dd',
'FROM',
' (SELECT to_char(trunc(sysdate)+(level - 1)/ 24,''FMHH'')ss,',
'        to_char(trunc(sysdate)+(level - 1)/ 24,''AM'')am,',
'        to_char(trunc(sysdate)+(level - 1)/ 24,''HH24'')ss24',
'  FROM dual CONNECT BY level <= 24),',
' (SELECT lpad(mod(15 * level, 60), 2, ''0'') dd',
'  FROM dual CONNECT BY level <= 4)',
'ORDER BY ss24, dd'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_query_owner=>'APXCENTRAL'
,p_return_column_name=>'SS_DD'
,p_display_column_name=>'SS_DD'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
end;
