,p_query_type=>'TABLE'
,p_query_table=>'STORE_ORDER_VW'
,p_query_where=>wwv_flow_string.join(wwv_flow_t_varchar2(
'STORE = NVL(:P1_STORE_FILTER,STORE)',
'AND BUSINESS_UNIT = NVL(:P1_BUSINESS_UNIT_FILTER, BUSINESS_UNIT)',
'--  AND REVIEW_GROUP_CODE = NVL(:P1_REVIEW_GROUP_FILTER, REVIEW_GROUP_CODE)  -- item is removed due to request. also removed from  "submit items"',
'AND STORE = NVL(:P1_USER_STORE, STORE)',
'AND BUSINESS_UNIT = NVL(:P1_USER_BUSINESS_UNIT, BUSINESS_UNIT)',
'--AND NWC.FRC_UTILS.IS_USERS_STORE(:APP_USER, STORE, BUSINESS_UNIT) = ''Y''',
'-- AND TRUNC(CREATED_DTM) >= TRUNC(SYSDATE)',
'AND (',
'    (TRUNC(CREATED_DTM) = TRUNC(SYSDATE) and :P1_USER_TYPE = ''STR'')',
'    OR',
'    -- "case" is used to get Friday date if today is Sun or Mon',
'    (TRUNC(CREATED_DTM) >= case when to_char(TRUNC(SYSDATE), ''DY'') in(''SUN'', ''MON'') then next_day(TRUNC(SYSDATE-4), ''FRIDAY'')',
'                                else TRUNC(SYSDATE-1)',
'                            end',
'      and TRUNC(CREATED_DTM) <= TRUNC(SYSDATE) ',
'      and :P1_USER_TYPE != ''STR'')',
')',
''))
