wwv_flow_api.create_region_column(
 p_id=>wwv_flow_api.id(3085867101678059278)
,p_name=>'CSS_STYLE_HDR'
,p_source_type=>'SQL_EXPRESSION'
,p_source_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--CASE WHEN (REVIEW_GROUP_CODE, STORE) IN (SELECT PRIMARY_SUPPLIER, STORE FROM STORE_VENDOR_MIN_RESTRICT_VW) THEN ''highlight_row_yellow'' ELSE '''' END',
'--WHEN (REVIEW_GROUP_CODE) IN (SELECT SUPPLIER FROM RMS_SUPS_VW WHERE MIN_ORDER_LEVEL <> ''N'' ) THEN ''highlight_row_yellow'' ',
'--CASE ',
'--WHEN VENDOR_MIN_MET = ''Y'' AND (REVIEW_GROUP_CODE) IN (SELECT SUPPLIER FROM RMS_SUPS_VW WHERE MIN_ORDER_LEVEL <> ''N'' ) THEN ''highlight_row_yellow'' ',
'--WHEN VENDOR_MIN_MET = ''N'' AND (REVIEW_GROUP_CODE) IN (SELECT SUPPLIER FROM RMS_SUPS_VW WHERE MIN_ORDER_LEVEL <> ''N'' ) AND NVL(REORDER_NEED,''N'') = ''N'' THEN ''highlight_row_red'' ',
'--WHEN VENDOR_MIN_MET = ''N'' AND (REVIEW_GROUP_CODE) IN (SELECT SUPPLIER FROM RMS_SUPS_VW WHERE MIN_ORDER_LEVEL <> ''N'' ) AND NVL(REORDER_NEED,''N'') = ''Y'' THEN ''highlight_row_yellow'' ',
'--ELSE ''highlight_row_white'' END',
'',
'CASE ',
'WHEN VENDOR_MIN_MET = ''N'' THEN ''highlight_row_yellow'' ',
'WHEN STORE_REVIEW_DTM IS NOT NULL OR REVIEW_DTM IS NOT NULL THEN ''highlight_row_green''',
'ELSE ''highlight_row_white'' END'))
,p_data_type=>'VARCHAR2'
,p_item_type=>'NATIVE_HIDDEN'
,p_display_sequence=>190
,p_attribute_01=>'N'
,p_filter_is_required=>false
,p_static_id=>'CSS_STYLE_HDR_COL'
,p_use_as_row_header=>false
,p_enable_sort_group=>true
,p_enable_control_break=>true
,p_include_in_export=>false
);
wwv_flow_api.create_region_column(
 p_id=>wwv_flow_api.id(3093463099337470344)
,p_name=>'MIN_ORDER_LIMIT'
,p_source_type=>'SQL_EXPRESSION'
,p_source_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'CASE WHEN S.MIN_ORDER_LEVEL <> ''N'' ',
'THEN DECODE(CDMOT1.CODE,''D'',''$'','''') || S.MIN_ORDER_VALUE1 || DECODE(CDMOT1.CODE,''D'','''', ''W'','' Kg'', '' '' || CDMOT1.CODE_DESC) || DECODE( S.MIN_ORDER_CONJ, ''O'' , '' or'', ''A'' , '' and'') || '' '' || DECODE( S.MIN_ORDER_CONJ, NULL, NULL, DECODE(CDMOT2.CODE,''D'''
||',''$'','''')  || S.MIN_ORDER_VALUE2 ||  DECODE(CDMOT2.CODE,''D'','''', ''W'','' Kg'', '' '' || CDMOT2.CODE_DESC)  ) || '' per '' || CDMOL.CODE_DESC',
'ELSE ''None'' END',
'',
'FROM RMS_SUPS_VW S',
'LEFT JOIN RMS_CODE_DETAIL_VW CDMOT1 ',
'ON S.MIN_ORDER_TYPE1 = CDMOT1.CODE',
'AND CDMOT1.CODE_TYPE = ''MNTP''',
'LEFT JOIN RMS_CODE_DETAIL_VW CDMOT2 ',
'ON S.MIN_ORDER_TYPE2 = CDMOT2.CODE',
'AND CDMOT2.CODE_TYPE = ''MNTP''',
'LEFT JOIN RMS_CODE_DETAIL_VW CDMOL',
'ON S.MIN_ORDER_LEVEL = CDMOL.CODE',
'AND CDMOL.CODE_TYPE = ''MNLV''',
'',
'WHERE S.SUPPLIER = REVIEW_GROUP_CODE'))
,p_data_type=>'VARCHAR2'
,p_item_type=>'NATIVE_DISPLAY_ONLY'
,p_heading=>'Vendor Minimum'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>200
,p_value_alignment=>'CENTER'
,p_attribute_02=>'VALUE'
,p_enable_filter=>true
,p_filter_operators=>'C:S:CASE_INSENSITIVE:REGEXP'
,p_filter_is_required=>false
,p_filter_text_case=>'MIXED'
,p_filter_exact_match=>true
,p_filter_lov_type=>'DISTINCT'
,p_static_id=>'MIN_ORDER_LIMIT_COL'
,p_use_as_row_header=>false
,p_enable_sort_group=>true
,p_enable_control_break=>true
,p_enable_hide=>true
,p_include_in_export=>false
,p_escape_on_http_output=>true
);
