 p_id=>wwv_flow_api.id(3693503667536503188)
,p_event_id=>wwv_flow_api.id(3693503563441503187)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT CASE WHEN REVIEW_CUTOFF_TIME IS NULL THEN ''Y'' ',
'                WHEN to_number(REPLACE(REVIEW_CUTOFF_TIME,'':'')) >= to_number(TO_CHAR(SYSDATE,''HH24MI'')) THEN ''Y'' ',
'                ELSE ''N'' ',
'                END ',
'     INTO :P1_ALLOW_STORE_REVIEW ',
'     FROM FRC_SETTINGS',
'    WHERE USER_TYPE = FRC_UTILS.GET_USER_TYPE(:APP_USER);',
'END;'))
,p_attribute_03=>'P1_ALLOW_STORE_REVIEW'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
