,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'--P1_ALLOW_EDIT_MODE',
'    SELECT CASE WHEN ((:P1_USER_TYPE = ''STR'' and :P1_STORE_REVIEW_DTM IS NOT NULL) OR :P1_REVIEW_DTM IS NOT NULL) then ''N''',
'                WHEN to_number(REPLACE(NVL(REVIEW_CUTOFF_TIME, ''2359''),'':'')) <= to_number(TO_CHAR(SYSDATE,''HH24MI'')) THEN ''N'' ',
'                ELSE ''Y''',
'            END,',
'            CASE WHEN to_number(REPLACE(NVL(REVIEW_CUTOFF_TIME, ''2359''),'':'')) <= to_number(TO_CHAR(SYSDATE,''HH24MI'')) THEN ''D'' ',
'                 WHEN ((:P1_USER_TYPE = ''STR'' and :P1_STORE_REVIEW_DTM IS NOT NULL) ) then ''N''',
'                 WHEN ((:P1_USER_TYPE != ''STR'' and :P1_REVIEW_DTM IS NOT NULL) ) then ''N''',
'                 ELSE ''Y''',
'            END',
'     INTO :P1_ALLOW_EDIT_MODE, :P1_SHOW_HIDE_BUTTONS',
'     FROM FRC_SETTINGS',
'    WHERE USER_TYPE = FRC_UTILS.GET_USER_TYPE(:APP_USER);',
'END;',
''))
