,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'SELECT ',
'CASE ',
'WHEN REVIEW_CUTOFF_TIME IS NULL THEN ''Y'' ',
'WHEN TO_CHAR(SYSDATE,''HH24MI'') BETWEEN to_number(REPLACE(NVL(REVIEW_START_TIME,''00:00''),'':'')) AND to_number(REPLACE(NVL(REVIEW_CUTOFF_TIME,''23:59''),'':'')) THEN ''Y'' ',
'ELSE ''N'' END INTO :P1_ALLOW_STORE_REVIEW ',
'FROM FRC_SETTINGS',
'WHERE USER_TYPE = FRC_UTILS.GET_USER_TYPE(:APP_USER);',
'END;'))
,p_attribute_03=>'P1_ALLOW_STORE_REVIEW'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
