wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(3980804738953988837)
,p_event_id=>wwv_flow_api.id(3980804647529988836)
,p_event_result=>'TRUE'
,p_action_sequence=>60
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE vUSER_TYPE VARCHAR2(3);',
'vALL_STORE_ORDERS_VALIDATED NUMBER;',
'BEGIN',
'    SELECT MAX(USER_TYPE) INTO vUSER_TYPE',
'    FROM FRC_USERS',
'    WHERE USER_ID = :APP_USER;',
'',
'    IF UPPER(vUSER_TYPE) = ''STR'' THEN',
'        UPDATE STORE_ORDER SET',
'        STORE_REVIEW_BY = :APP_USER,',
'        STORE_REVIEW_DTM = SYSDATE',
'        WHERE BATCH_ID = :P1_BATCH_ID',
'        AND STORE = :P1_STORE',
'        AND BUSINESS_UNIT = :P1_BUSINESS_UNIT',
'        AND REVIEW_GROUP_CODE  = :P1_REVIEW_GROUP;',
'    ELSE',
'        UPDATE STORE_ORDER SET',
'        REVIEW_BY = :APP_USER,',
'        REVIEW_DTM = SYSDATE',
'        WHERE BATCH_ID = :P1_BATCH_ID',
'        AND STORE = :P1_STORE',
'        AND BUSINESS_UNIT = :P1_BUSINESS_UNIT',
'        AND REVIEW_GROUP_CODE  = :P1_REVIEW_GROUP;',
'    END IF;',
'',
'    SELECT COUNT(1) INTO vALL_STORE_ORDERS_VALIDATED',
'    FROM STORE_ORDER_VW WHERE STORE_REVIEW_DTM IS NULL',
'    AND STORE = FRC_UTILS.GET_USER_DFLT_STORE(:APP_USER)',
'    AND (TRUNC(CREATED_DTM) = TRUNC(SYSDATE) and :P1_USER_TYPE = ''STR'');',
'',
'    :P1_ALL_STORE_ORDERS_VALIDATED := vALL_STORE_ORDERS_VALIDATED;',
'',
'END;'))
,p_attribute_02=>'P1_BATCH_ID,P1_BUSINESS_UNIT,P1_STORE,P1_REVIEW_GROUP'
,p_attribute_03=>'P1_ALL_STORE_ORDERS_VALIDATED'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
