wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(3693500864962503160)
,p_event_id=>wwv_flow_api.id(2208253313664168013)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT CASE WHEN to_number(TO_CHAR(SYSDATE,''HH24MI'')) BETWEEN to_number(REPLACE(NVL(REVIEW_START_TIME,''00:00''),'':'')) AND  to_number(REPLACE(NVL(REVIEW_CUTOFF_TIME,''23:59''),'':'')) THEN ''Y''',
'                ELSE ''N'' ',
'                END ',
'     INTO :P1_ALLOW_STORE_REVIEW ',
'     FROM FRC_SETTINGS',
'    WHERE USER_TYPE = FRC_UTILS.GET_USER_TYPE(:APP_USER);',
'END;'))
,p_attribute_03=>'P1_ALLOW_STORE_REVIEW'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(3693501117247503162)
,p_event_id=>wwv_flow_api.id(2208253313664168013)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'--P1_ALLOW_EDIT_MODE',
'    SELECT CASE WHEN ((:P1_USER_TYPE = ''STR'' and :P1_STORE_REVIEW_DTM IS NOT NULL) OR :P1_REVIEW_DTM IS NOT NULL) then ''N''',
'                WHEN to_number(TO_CHAR(SYSDATE,''HH24MI'')) NOT BETWEEN to_number(REPLACE(NVL(REVIEW_START_TIME,''00:00''),'':'')) AND to_number(REPLACE(NVL(REVIEW_CUTOFF_TIME,''23:59''),'':'')) THEN ''N''',
'                ELSE ''Y''',
'            END,',
'            CASE WHEN to_number(TO_CHAR(SYSDATE,''HH24MI'')) NOT BETWEEN to_number(REPLACE(NVL(REVIEW_START_TIME,''00:00''),'':'')) AND to_number(REPLACE(NVL(REVIEW_CUTOFF_TIME,''23:59''),'':'')) THEN ''D''',
'                 WHEN ((:P1_USER_TYPE = ''STR'' and :P1_STORE_REVIEW_DTM IS NOT NULL) ) then ''N''',
'                 WHEN ((:P1_USER_TYPE != ''STR'' and :P1_REVIEW_DTM IS NOT NULL) ) then ''N''',
'                 ELSE ''Y''',
'            END',
'     INTO :P1_ALLOW_EDIT_MODE, :P1_SHOW_HIDE_BUTTONS',
'     FROM FRC_SETTINGS',
'    WHERE USER_TYPE = FRC_UTILS.GET_USER_TYPE(:APP_USER);',
'END;',
''))
,p_attribute_02=>'P1_USER_TYPE,P1_REVIEW_DTM,P1_STORE_REVIEW_DTM'
,p_attribute_03=>'P1_ALLOW_EDIT_MODE,P1_SHOW_HIDE_BUTTONS'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
