'//set the static id field on your interactive grid and put the value on gridID variable',
'var gridID = "ORDERS_IG";',
'var ig$ = apex.region(gridID).widget();',
'var grid = ig$.interactiveGrid("getViews","grid");',
'',
'',
'var view$ = apex.region("ORDERS_IG").call("getViews").grid.view$;',
'//set to last selected page before submit',
'var lastSelectedPage = JSON.parse(localStorage.getItem(''lastSelectedPage''));',
