'var lastSelectedRecord = JSON.parse(localStorage.getItem(''lastSelectedRecord''));',
'if (lastSelectedRecord)',
'    grid.setSelectedRecords(JSON.parse(localStorage.getItem(''lastSelectedRecord'')));',
'',
'//apex.region("ORDERS_IG").widget().interactiveGrid(''setSelectedRecords'', lastSelectedRecord);',
'//now reset the values back to first record',
