wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(3956164676397157355)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_api.id(3956160560594157313)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'SOQ - Save Interactive Grid Data'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'',
'IF :APEX$ROW_STATUS = ''U'' THEN',
'    UPDATE STORE_ORDER_SKU_VW',
'    SET REASON_FOR_ADDITION = :REASON_FOR_ADDITION,',
'        NOTE = :NOTE,',
'        FINAL_ORDER =   CASE ',
'                            WHEN TRUNC(SYSDATE) BETWEEN :SS_START_DTM AND :SS_END_DTM AND NVL(:WAIT_FOR_NEXT_SAIL_IND,''Y'') = ''Y'' THEN 0 ',
'                            ELSE :SUGGESTED_ORDER_QTY_ADJ + NVL(:PDT_ADDITIONS,0) + NVL(:STORE_ADDITION_CASES,0) ',
'                        END,',
'        STORE_ADDITION_CASES = :STORE_ADDITION_CASES,',
'        WAIT_FOR_NEXT_SAIL_IND = :WAIT_FOR_NEXT_SAIL_IND',
'    WHERE BATCH_ID = :BATCH_ID',
'    AND BUSINESS_UNIT = :BUSINESS_UNIT',
'    AND STORE = :STORE',
'    AND SKU = :SKU',
'    AND REVIEW_GROUP_CODE = :REVIEW_GROUP_CODE',
'    AND PRIMARY_SUPPLIER = :PRIMARY_SUPPLIER; ',
'',
'END IF; ',
'',
'',
'',
'',
'END;'))
,p_attribute_05=>'Y'
,p_attribute_06=>'N'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
