,p_region_id=>wwv_flow_api.id(3956160560594157313)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CHECK_IF_VENDOR_MIN_REACHED'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE vRESULT VARCHAR2(1);',
'pBATCH_ID NUMBER;',
'pSTORE NUMBER;',
'pBUSINESS_UNIT VARCHAR2(3);',
'pREVIEW_GROUP  VARCHAR2(30);',
'BEGIN',
'',
'    pBATCH_ID := APEX_APPLICATION.g_x01;',
'    pSTORE := APEX_APPLICATION.g_x02;',
'    pBUSINESS_UNIT := APEX_APPLICATION.g_x03;',
'    pREVIEW_GROUP := APEX_APPLICATION.g_x04;',
'',
'    vRESULT := FRC_UTILS.TOTAL_REACHED_VENDOR_MIN(pBATCH_ID, pSTORE, pBUSINESS_UNIT, pREVIEW_GROUP);',
'    apex_json.open_object;',
'    apex_json.open_array(''item'');',
'    apex_json.open_object;',
'    apex_json.write(''DisplayMessage'',vRESULT);',
'    apex_json.close_object;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'EXCEPTION WHEN OTHERS THEN',
'   HTP.P(''"Error checking"'');',
'END'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
