'                            col001  AS BUSINESS_UNIT      ,',
'                            col002  AS PAY_DAY_TYPE       ,',
'                            col003  AS PAY_MONTH          ,',
'                            col004  AS CY_PAY_START_DTM   ,',
'                            col005  AS CY_PAY_END_DTM             ',
'                          ',
