,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'If you select this checkbox, the application will save your username in a persistent browser cookie named "LOGIN_USERNAME_COOKIE".',
'When you go to the login page the next time,',
'the username field will be automatically populated with this value.',
'</p>',
'<p>',
'If you deselect this checkbox and your username is already saved in the cookie,',
'the application will overwrite it with an empty value.',
'You can also use your browser''s developer tools to completely remove the cookie.',
'</p>'))
,p_attribute_01=>'1'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(3976965014392007259)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Username Cookie'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex_authentication.send_login_username_cookie (',
'    p_username => lower(:P9999_USERNAME),',
'    p_consent  => :P9999_REMEMBER = ''Y'' );'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(3976964629975007258)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Login'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'vALLOW_USER_LOGIN VARCHAR2(1);',
'vLOGIN_ALLOWED_FROM VARCHAR2(5);',
'vLOGIN_ALLOWED_TO VARCHAR2(5);',
'BEGIN',
'    FOR C IN ',
'    (',
'        SELECT ',
'        CASE ',
'            WHEN REPLACE(NVL(LOGIN_ALLOWED_FROM,''00:00''),'':'') <= REPLACE(NVL(LOGIN_ALLOWED_TO,''23:59''),'':'') AND TO_CHAR(SYSDATE,''HH24MI'') BETWEEN REPLACE(NVL(LOGIN_ALLOWED_FROM,''00:00''),'':'') and REPLACE(NVL(LOGIN_ALLOWED_TO,''23:59''),'':'') THEN ''Y'' ',
'            WHEN REPLACE(NVL(LOGIN_ALLOWED_FROM,''00:00''),'':'') > REPLACE(NVL(LOGIN_ALLOWED_TO,''23:59''),'':'') AND (TO_CHAR(SYSDATE,''HH24MI'') < REPLACE(NVL(LOGIN_ALLOWED_TO,''00:00''),'':'') OR TO_CHAR(SYSDATE,''HH24MI'') >= REPLACE(NVL(LOGIN_ALLOWED_FROM,''23:'
||'59''),'':'')) THEN ''Y'' ',
'            ELSE ''N'' ',
'        END AS ALLOW_USER_LOGIN,',
'        NVL(LOGIN_ALLOWED_FROM,''00:00'') AS LOGIN_ALLOWED_FROM,',
'        NVL(LOGIN_ALLOWED_TO,''23:59'') AS LOGIN_ALLOWED_TO',
'        INTO ',
'        vALLOW_USER_LOGIN,vLOGIN_ALLOWED_FROM,vLOGIN_ALLOWED_TO',
'        FROM FRC_SETTINGS',
'        WHERE USER_TYPE = FRC_UTILS.GET_USER_TYPE(upper(:P9999_USERNAME))',
'    )',
'    LOOP',
'        vALLOW_USER_LOGIN := C.ALLOW_USER_LOGIN;',
'        vLOGIN_ALLOWED_FROM := C.LOGIN_ALLOWED_FROM;',
'        vLOGIN_ALLOWED_TO := C.LOGIN_ALLOWED_TO;',
'    END LOOP;',
'',
'    IF vALLOW_USER_LOGIN IS NULL THEN',
'        APEX_ERROR.ADD_ERROR (',
'            p_message          => ''The user is not properly configured in Users table'',',
'            p_display_location => APEX_ERROR.C_INLINE_WITH_FIELD_AND_NOTIF,',
'            p_page_item_name   => ''P9999_USERNAME''',
'        );',
'    ELSIF vALLOW_USER_LOGIN = ''N'' THEN',
'        APEX_ERROR.ADD_ERROR (',
'            p_message          => ''Login is allowed between '' || vLOGIN_ALLOWED_FROM || '' and '' || vLOGIN_ALLOWED_TO || '' only'',',
'            p_display_location => APEX_ERROR.C_INLINE_WITH_FIELD_AND_NOTIF,',
'            p_page_item_name   => ''P9999_USERNAME''',
'        );',
'    ELSE',
'        apex_authentication.login(',
'            p_username => :P9999_USERNAME,',
'            p_password => :P9999_PASSWORD );',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(3976965840963007259)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_SESSION_STATE'
,p_process_name=>'Clear Page(s) Cache'
,p_attribute_01=>'CLEAR_CACHE_CURRENT_PAGE'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(3976965465518007259)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get Username Cookie'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P9999_USERNAME := apex_authentication.get_login_username_cookie;',
':P9999_REMEMBER := case when :P9999_USERNAME is not null then ''Y'' end;'))
,p_process_clob_language=>'PLSQL'
);
end;
